def icon(name):return '<svg class="icon" viewBox="0 0 96 80" aria-hidden="true">'+ICONS[name]+'</svg>'
def shell(title,body,script='',label='Módulo 1 · Ser-se humano'):
 page=f'''<!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="description" content="Direitos humanos, democracia e interpretação. EPI · INTP26."><title>{html.escape(title)} · Cidadania · EPI</title><style>{CSS}</style></head><body><main class="pg"><div class="marca">{LOGO}<span>Cidadania e Desenvolvimento<br>Interpretação — Ator/atriz · INTP26</span></div>{body}<footer>EPI · Pedro Fernandes · 2026/2027<br>{label}</footer></main>{script}</body></html>'''
 return '\n'.join(line.expandtabs(2).rstrip() for line in page.splitlines())+'\n'
def head(title,sub,back='index.html'):
 return f'<header class="p-cab"><p class="p-etiqueta"><a href="{back}">← Cidadania · Módulo 1</a></p><h1>{title}</h1><p class="p-sub">{sub}</p></header>'
def refs(keys):
 return '<ul class="fontes">'+''.join(f'<li><a href="{SOURCES[k][1]}" target="_blank" rel="noopener">{SOURCES[k][0]}</a></li>' for k in keys)+'</ul>'
for i,step in enumerate(STEPS):
 previous=f'passo-{int(step["id"])-1:02d}.html' if i else 'index.html'
 following=f'passo-{int(step["id"])+1:02d}.html' if i<9 else 'ensaio-2.html'
 essays=''
 if i==4:essays='<section class="materiais"><h2>Primeiro ensaio</h2><a href="ensaio-1.html">Abrir a ficha de Truman</a><a href="materiais/Truman_Show_Ficha_Interpretacao.pdf">Descarregar a ficha em PDF</a></section>'
 if i==5:essays='<section class="materiais"><h2>Segundo filme</h2><a href="guiao-2.html">Guião de investigação · Doze Homens em Fúria</a></section>'
 if i==9:essays='<section class="materiais"><h2>Segundo ensaio</h2><a href="guiao-2.html">Abrir o guião</a><a href="ensaio-2.html">Abrir a ficha «Decidir sobre o outro»</a></section>'
 data=json.dumps(step,ensure_ascii=False).replace('</','<\\/')
 body=head(step['title'],step['subtitle'])+icon(step['icon'])+f'<section class="exercicio"><div id="atividade"></div><aside class="feedback" id="feedback" role="status" aria-live="polite" hidden></aside></section><noscript><p>Ativa o JavaScript para usar as escolhas interativas. Os materiais e as fontes continuam disponíveis abaixo.</p></noscript><div class="barra nao-imprimir"><span id="estado">Por explorar</span><button class="c-sec" id="reiniciar" type="button">Recomeçar</button></div><details><summary>Antes de explorar</summary><p>{step["intro"]}</p><p>{step["aim"]}</p></details><details><summary>Fontes e ligações</summary>{refs(step["refs"])}</details>'+essays+f'<nav class="barra"><a class="c-sec" href="{previous}">← Voltar</a><a class="c-prim" href="{following}">'+('Próximo passo →' if i<9 else 'Ir para o segundo ensaio →')+'</a></nav>'
 script=f'<script type="application/json" id="dados">{data}</script><script>{JS}</script>'
 (OUT/f'passo-{step["id"]}.html').write_text(shell(step['title'],body,script))

cards=''.join(f'<a class="passo" href="passo-{s["id"]}.html"><span class="n">{s["id"]}</span>{icon(s["icon"])}<b>{s["title"]}</b><p>{s["subtitle"]}</p><span class="badge" data-progresso="{s["id"]}">Por explorar</span></a>' for s in STEPS)
body=head('Ser-se humano','Quem conta como pessoa — e quem decide?',back='../index.html')+'<p class="p-lead">Direitos humanos e democracia · dez passos · dois filmes · dois ensaios.</p><p class="ler">Começa com <i>The Truman Show</i>. Recupera as obras que já estudámos, investiga as escolhas de quem atua e decide e regressa à escrita com uma posição fundamentada.</p><nav class="passos" aria-label="Dez passos do módulo">'+cards+'</nav>'
body+='''<section class="materiais"><h2>Investigar e escrever</h2><a href="guiao-1.html">Guião 1 · Preparar o trabalho sobre Truman</a><a href="ensaio-1.html">Ficha 1 · A quem pertence a vida de Truman?</a><a href="guiao-2.html">Guião 2 · Preparar Doze Homens em Fúria</a><a href="ensaio-2.html">Ficha 2 · Decidir sobre o outro</a></section><section class="materiais"><h2>O que já trabalhámos</h2><a href="../aula-1.html">O que vemos · Platão, CHIROPTERA e This is Water</a><a href="../aula-2.html">O que somos · Sísifo e Abramović</a><a href="../projeto.html">Pergunta Humana · materiais do projeto anterior</a><a href="anteriores/ficha-cd1.html">Primeira ficha de Cidadania · dignidade e investigação</a></section><details><summary>Como usar</summary><p>Escolhe, associa, abre pistas e compara posições. A justificação é feita oralmente. Usa os guiões e as fichas próprias para investigar e escrever os ensaios.</p><p>O estado «Explorado» fica apenas neste aparelho e não é uma nota. Não precisas de criar uma conta. O professor pode usar a página no projetor e a turma responder em papel e no debate.</p></details>'''
script='''<script>document.querySelectorAll('[data-progresso]').forEach(el=>{try{if(localStorage.getItem('epi-cd-m1-v1-'+el.dataset.progresso)==='explorado')el.textContent='Explorado';}catch{}});</script>'''
(OUT/'index.html').write_text(shell('Ser-se humano',body,script))

GUIAO2='''<p>Vê <i>Doze Homens em Fúria</i>, de Sidney Lumet (1957), na aula. Observa como as personagens falam, escutam, ocupam o espaço e alteram — ou mantêm — as suas posições.</p><h2>Escolhe dois caminhos de investigação</h2><ol><li><b>Prova e interpretação.</b> O que é apresentado como evidência? Que conclusões ultrapassam aquilo que se pode demonstrar?</li><li><b>Preconceito e igualdade.</b> Que ideias sobre a origem ou a pertença de uma pessoa influenciam a decisão?</li><li><b>Maioria e discordância.</b> Quando é que discordar ajuda o grupo a decidir melhor?</li><li><b>Ator e personagem.</b> Escolhe uma personagem: que objetivo procura, que ação usa e o que muda quando encontra resistência? Relaciona com Stanislavski e o trabalho do Actors Studio.</li><li><b>A pessoa ausente.</b> Quem é discutido sem estar na sala? Relaciona com Truman, Sylvia e a pergunta «quem nunca fala?».</li><li><b>Autoridade e responsabilidade.</b> Relaciona uma decisão do filme com Pinter, Tchékhov ou Abramović. Explica também uma diferença entre as situações.</li></ol><h2>Reúne para a próxima aula</h2><p>Duas fontes identificadas; uma cena de cada filme; uma ligação a outra referência estudada; uma objeção à tua posição; uma pergunta de investigação.</p><p>Regista por palavras tuas, em papel. Identifica autor ou instituição, título e ligação de cada fonte. Separa o que observaste da tua interpretação.</p><h2>Atenção ao contexto</h2><p>O filme apresenta um júri dos Estados Unidos. A análise centra-se na evidência, na igualdade e na responsabilidade de decidir; não serve como descrição do sistema judicial português. Distingue presunção de inocência de certeza sobre o que aconteceu.</p>'''
(OUT/'guiao-2.html').write_text(shell('Guião de investigação · Segundo filme',head('Antes de decidir','Doze Homens em Fúria · guião de investigação')+'<article class="apoio">'+GUIAO2+'</article><section class="materiais"><h2>Fontes de partida</h2>'+refs(['filme2','direitos','studio','pinter','kane'])+'<a href="materiais/Doze_Homens_Guiao_Investigacao.pdf">Descarregar o guião em PDF</a></section>'))

ENSAIO2='''<p>Compara <i>The Truman Show</i> e <i>Doze Homens em Fúria</i>. Usa uma terceira referência estudada para aprofundar a tua posição. O objetivo é explicar como se protege a dignidade de alguém quando outros têm poder para decidir sobre a sua vida.</p><h2>1 · Da cena ao problema</h2><p>Escolhe uma cena de cada filme. Em cada uma, identifica quem decide, que informação possui, quem é afetado e que possibilidade existe de contestar.</p><div class="campo-papel"></div><h2>2 · Do problema ao direito</h2><p>Relaciona as duas cenas com dois direitos ou princípios democráticos. Explica a ligação; não basta indicar o número de um artigo.</p><div class="campo-papel"></div><h2>3 · Uma terceira referência</h2><p>Escolhe Platão, Sísifo, The Egg, Shakespeare, Pinter, Sarah Kane, Abramović, CHIROPTERA ou Stanislavski / Actors Studio. Apresenta uma relação e uma diferença que ajudem a compreender os filmes.</p><div class="campo-papel"></div><h2>4 · A tua tese e a objeção</h2><p>Formula uma posição, dois argumentos e uma objeção real. Explica como responderias à objeção sem atacar quem a apresenta.</p><div class="campo-papel"></div><h2>5 · Ensaio 2</h2><p>Escreve <b>400 a 600 palavras</b> sobre uma das perguntas:</p><ul><li>Quando é que proteger alguém passa a ser controlar a sua vida?</li><li>Pode uma maioria tomar uma decisão injusta?</li><li>Que responsabilidade temos quando vemos uma pessoa ser tratada como um objeto?</li><li>Como pode um ator compreender o outro sem deixar de avaliar as suas ações?</li></ul><p>Apresenta uma tese, dois argumentos, uma cena de cada filme, uma ligação à terceira referência, uma objeção e uma conclusão. Identifica pelo menos duas fontes no final; a lista de referências não entra na contagem de palavras.</p><p>Podes propor outra pergunta ao professor, desde que relacione os filmes com direitos humanos e democracia.</p><h2>Antes de entregar</h2><ul><li>A tese responde à pergunta escolhida?</li><li>Os exemplos são analisados em vez de apenas resumidos?</li><li>A comparação inclui uma diferença entre as obras?</li><li>A objeção é enfrentada com fundamento?</li><li>As fontes estão identificadas e a linguagem foi revista?</li></ul>'''
(OUT/'ensaio-2.html').write_text(shell('Ficha · Ensaio 2',head('Decidir sobre o outro','Dois filmes · uma posição fundamentada')+'<article class="apoio">'+ENSAIO2+'</article><section class="materiais"><a href="materiais/Doze_Homens_Ficha_Ensaio.pdf">Descarregar a ficha em PDF</a><a href="guiao-2.html">Consultar o guião de investigação</a></section>'))

GUIAO1='''<p>Recupera Platão, Sísifo, Marina Abramović, The Egg e CHIROPTERA. Relaciona as perguntas que abriram com The Truman Show.</p><h2>Escolhe dois caminhos</h2><ul><li><b>Liberdade:</b> que informação e possibilidades são necessárias para escolher?</li><li><b>Dignidade:</b> quando passa uma pessoa a ser tratada como produto?</li><li><b>Representação:</b> que distingue Marlon e Meryl de Sylvia?</li><li><b>Consentimento:</b> que relação e que diferença existem entre a tempestade e Rhythm 0?</li><li><b>Democracia:</b> como se deve limitar um poder como o de Christof?</li></ul><h2>Traz para a aula</h2><p>Duas fontes identificadas, três ideias por palavras tuas, uma cena e uma pergunta sobre a responsabilidade de quem atua ou assiste.</p>'''
(OUT/'guiao-1.html').write_text(shell('Guião · Truman',head('Que humanidade queremos?','Preparar a investigação sobre Truman')+'<article class="apoio">'+GUIAO1+'</article><section class="materiais">'+refs(['direitos','abramovic','egg','chiroptera'])+'<a href="materiais/EPI_Cidadania_Guiao_Investigacao.pdf">Guião completo em PDF</a></section>'))
body=head('A quem pertence a vida de Truman?','Ensaio 1 · interpretar, planear e escrever')+'''<article class="apoio"><p>A ficha integra o texto de apoio «A quem pertence a vida de Truman?», sete perguntas de interpretação, uma planificação e espaço para o primeiro ensaio.</p><h2>A pergunta</h2><p>Uma vida confortável é necessariamente uma vida livre?</p><p>Escreve 250 a 350 palavras. Apresenta a tua posição, dois argumentos, exemplos do filme e uma objeção. Relaciona liberdade, dignidade e responsabilidade.</p><p>Na ficha, podes formular o título à tua escolha. O tema geral mantém-se: liberdade, dignidade e responsabilidade numa sociedade democrática.</p></article><section class="materiais"><a class="c-prim" href="materiais/Truman_Show_Ficha_Interpretacao.pdf">Abrir a ficha em PDF →</a><a href="guiao-1.html">Consultar o guião</a><a href="passo-05.html">Explorar a construção de argumentos</a></section>'''
(OUT/'ensaio-1.html').write_text(shell('Ensaio 1 · Truman',body))

rows=''.join(f'<tr><td>{s["id"]}</td><td><a href="passo-{s["id"]}.html">{s["title"]}</a><br>{s["aim"]}</td><td>3 h</td></tr>' for s in STEPS)
body=head('Percurso do professor','30 horas · dez passos · dois ensaios')+f'''<p>A distribuição de três horas por passo é uma proposta de organização do módulo. Inclui visionamento, leitura, investigação, debate e escrita; não é a duração estimada do exercício online. Ajustar ao trabalho já realizado e ao horário efetivo.</p><p>Truman entra no passo 1. O primeiro ensaio surge no passo 5. Doze Homens em Fúria entra no passo 6, antes do trabalho sobre deliberação, fontes e segundo ensaio.</p><table><thead><tr><th>Passo</th><th>Trabalho</th><th>Horas</th></tr></thead><tbody>{rows}<tr><td colspan="2">Total</td><td>30 h</td></tr></tbody></table><h2>Como conduzir as fichas</h2><p>Projetar a página. A turma escolhe ou associa e justifica oralmente antes de abrir o comentário. Perguntar que pista sustenta a escolha e que informação a poderia alterar. Não tratar o comentário como uma resposta a memorizar.</p><p>As atividades não pedem produção textual. Os registos de investigação e os ensaios ficam nos guiões e fichas próprios. Não são recolhidos nomes, respostas escritas ou votações individuais.</p><h2>Dois ensaios</h2><p>Ensaio 1: 250–350 palavras, centrado em Truman, com feedback sobre tese, argumentos e objeção. Ensaio 2: 400–600 palavras, relacionando os dois filmes e uma terceira referência, com pelo menos duas fontes identificadas.</p><p>Grelha sugerida, sobre 20: tese 3; argumentos e direitos/democracia 5; análise e comparação de exemplos 4; objeção e resposta 3; organização e linguagem 3; fontes 2.</p><h2>Materiais existentes</h2><p>As aulas anteriores e o projeto Pergunta Humana continuam acessíveis. A ficha oficial do módulo foi conservada: a presente organização e os dois ensaios constituem a proposta atual de percurso, sem substituir administrativamente a avaliação registada nessa ficha.</p><h2>Precisão e fontes</h2><p>Não equiparar sistema de Stanislavski e Método de Strasberg. Não apresentar uma expectativa narrativa como necessidade moral. Não transformar Sarah Kane ou as suas vozes em diagnósticos. O júri norte-americano do filme não descreve os tribunais portugueses.</p><p>Os casos inventados estão identificados. Não são reproduzidos textos integrais de Pinter ou Kane, nem disponibilizados os filmes completos. As fontes conduzem a instituições e páginas identificadas.</p><section class="materiais"><a href="materiais/Truman_Show_Guia_Professor.pdf">Respostas e critérios · Ensaio 1</a><a href="materiais/Doze_Homens_Guia_Professor.pdf">Respostas e critérios · Ensaio 2</a></section>'''
